const net=require('net'),crypto=require('crypto');
const key=crypto.randomBytes(16).toString('base64');
const r=net.connect(8081,'127.0.0.1',()=>{
  r.write('GET /chat HTTP/1.1\r\nHost: 127.0.0.1:8081\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Key: '+key+'\r\nSec-WebSocket-Version: 13\r\n\r\n');
});
let buf='';
r.on('data',d=>{
  buf+=d;
  const i=buf.indexOf('\r\n\r\n');
  if(i>=0){
    const head=buf.slice(0,i);
    const accept=crypto.createHash('sha1').update(key+'258EAFA5-E914-47DA-95CA-C5AB0DC85B11').digest('base64');
    const got=(head.match(/Sec-WebSocket-Accept: (.*)/)||[])[1];
    console.log(head.split('\r\n')[0]);
    console.log('expected accept:', accept);
    console.log('server   accept:', got);
    console.log(got===accept && /101/.test(head) ? 'HANDSHAKE OK' : 'HANDSHAKE FAIL');
    r.destroy(); process.exit(0);
  }
});
setTimeout(()=>{console.log('TIMEOUT');process.exit(4)},5000);
"; RC=$?; kill $SRV 2>/dev/null; cat /tmp/collab-server.log; echo "handshake-exit=$RC"","timeout":30}
